func readAutoSignInFixture(name string) ([]byte, error) {
	return os.ReadFile(filepath.Join("reference", "adapters", name))
}
func TestSource22AdapterOracles(t *testing.T) {
	for _, c := range []struct {
		file  string
		count int
	}{{"fixed-reference.json", 105}, {"ocr-reference.json", 147}, {"quiz-reference.json", 180}, {"dynamic-reference.json", 96}, {"json-reference.json", 255}, {"simple-reference.json", 153}, {"tjupt-reference.json", 131}, {"mteam-flow-reference.json", 51}} {
		t.Run(c.file, func(t *testing.T) { checkInstalledAdapterReference(t, c.file, c.count) })
	}
}
